function appendIconNode(parent, definition) {
  const [tag, attributes = {}, children = []] = definition;
  const node = document.createElementNS(SVG_NS, tag);
  Object.entries(attributes).forEach(([name, value]) => {
    if (name !== "key" && value !== undefined && value !== null) {
      node.setAttribute(name, String(value));
    }
  });
  if (Array.isArray(children)) {
    children.forEach((child) => appendIconNode(node, child));
  }
  parent.append(node);
}

export function createIcon(name, options = {}) {
  const resolvedOptions = typeof options === "number" ? { size: options } : options;
  const {
    size = 18,
    strokeWidth = 1.75,
    className = "",
    label = "",
  } = resolvedOptions;
  const iconName = Object.hasOwn(ICONS, name) ? name : "File";
  const svg = document.createElementNS(SVG_NS, "svg");
  svg.setAttribute("viewBox", "0 0 24 24");
  svg.setAttribute("width", String(size));
  svg.setAttribute("height", String(size));
  svg.setAttribute("fill", "none");
  svg.setAttribute("stroke", "currentColor");
  svg.setAttribute("stroke-width", String(strokeWidth));
  svg.setAttribute("stroke-linecap", "round");
  svg.setAttribute("stroke-linejoin", "round");
  svg.setAttribute("focusable", "false");
  svg.dataset.icon = iconName;
  svg.classList.add("mw-lucide", "mw-icon");
  String(className)
    .split(/\s+/)
    .filter(Boolean)
    .forEach((token) => svg.classList.add(token));
  if (label) {
    svg.setAttribute("role", "img");
    svg.setAttribute("aria-label", label);
  } else {
    svg.setAttribute("aria-hidden", "true");
  }
  ICONS[iconName].forEach((definition) => appendIconNode(svg, definition));
  return svg;
}

export function setIcon(target, name, options = {}) {
  target.replaceChildren(createIcon(name, options));
  target.dataset.mwIcon = name;
  return target;
}

export function iconForFile(value) {
  const name = String(value || "").toLowerCase().split(/[\\/]/).pop() || "";
  if (/\.(png|jpe?g|gif|webp|bmp|svg|ico)$/.test(name)) return "FileImage";
  if (/\.(py|js|jsx|ts|tsx|sh|ps1|bat|cmd|c|cc|cpp|h|hpp|java|go|rs|r|m|sql|tex|cls|sty)$/.test(name)) return "FileCode2";
  if (/\.(json|jsonl|ya?ml|toml|xml|geojson)$/.test(name)) return "FileJson";
  if (/\.(csv|tsv|xls|xlsx|ods)$/.test(name)) return "FileSpreadsheet";
  if (/\.(zip|7z|rar|tar|gz|bz2|xz)$/.test(name)) return "FileArchive";
  if (/\.drawio$/.test(name)) return "Workflow";
  if (/\.pdf$/.test(name)) return "FileType2";
  if (/\.(md|markdown|txt|doc|docx|rtf|bib|ris)$/.test(name)) return "FileText";
  return "File";
}

export function fileVisual(value) {
  const name = String(value || "").toLowerCase().split(/[\\/]/).pop() || "";
  const extension = name.includes(".") ? name.split(".").pop() || "" : "";
  const icon = iconForFile(name);
  if (/\.(md|markdown)$/.test(name)) return { icon, kind: "markdown", label: "Markdown" };
  if (/\.pdf$/.test(name)) return { icon, kind: "pdf", label: "PDF" };
  if (/\.(doc|docx|rtf)$/.test(name)) return { icon, kind: "document", label: "Document" };
  if (/\.(xls|xlsx|ods|csv|tsv)$/.test(name)) return { icon, kind: "spreadsheet", label: "Spreadsheet" };
  if (/\.(png|jpe?g|gif|webp|bmp|svg|ico)$/.test(name)) return { icon, kind: "image", label: "Image" };
  if (/\.(py|js|jsx|ts|tsx|sh|ps1|bat|cmd|c|cc|cpp|h|hpp|java|go|rs|r|m|sql|tex|cls|sty)$/.test(name)) {
    return { icon, kind: "code", label: extension ? extension.toUpperCase() : "Code" };
  }
  if (/\.(json|jsonl|ya?ml|toml|xml|geojson)$/.test(name)) return { icon, kind: "data", label: extension.toUpperCase() };
  if (/\.(zip|7z|rar|tar|gz|bz2|xz)$/.test(name)) return { icon, kind: "archive", label: "Archive" };
  if (/\.drawio$/.test(name)) return { icon, kind: "diagram", label: "DrawIO" };
  return { icon, kind: "file", label: extension ? extension.toUpperCase() : "File" };
}

export const iconNames = Object.freeze(Object.keys(ICONS));
